import { Hammer, HardHat, ClipboardList, X } from "lucide-react"
import { VSCodeProgressRing } from "@vscode/webview-ui-toolkit/react"

export interface ActionIndicatorProps {
	mode?: "loading" | "thinking" | "building" | "completed" | "planning" | "waiting" | "failure"
}

// Keyframe animations defined as style elements
const keyframesStyle = `
@keyframes hammerRotate {
	0% { transform: rotate(-45deg); }
	12.5% { transform: rotate(-22.5deg); }
	25% { transform: rotate(0deg); }
	37.5% { transform: rotate(22.5deg); }
	50% { transform: rotate(45deg); }
	62.5% { transform: rotate(22.5deg); }
	75% { transform: rotate(0deg); }
	87.5% { transform: rotate(-22.5deg); }
	100% { transform: rotate(-45deg); }
}

@keyframes thinkingPulse {
	0% { opacity: 0.6; transform: scale(0.95); }
	50% { opacity: 1; transform: scale(1.05); }
	100% { opacity: 0.6; transform: scale(0.95); }
}

@keyframes planningWrite {
	0% { transform: translateY(0); }
	50% { transform: translateY(-2px); }
	100% { transform: translateY(0); }
}
`

export const ActionIndicator: React.FC<ActionIndicatorProps> = ({ mode = "loading" }) => {
	let icon = null
	if (mode === "loading" || mode === "waiting") {
		icon = (
			<div style={{ transform: "scale(0.55)", transformOrigin: "center" }}>
				<VSCodeProgressRing />
			</div>
		)
	} else if (mode === "building") {
		icon = (
			<>
				<style>{keyframesStyle}</style>
				<div
					style={{
						animation: "hammerRotate 1.5s cubic-bezier(0.1, 0, 0.2, 1) infinite",
						transformOrigin: "left bottom",
					}}>
					<Hammer size={16} strokeWidth={1} />
				</div>
			</>
		)
	} else if (mode === "thinking") {
		icon = (
			<>
				<style>{keyframesStyle}</style>
				<div
					style={{
						animation: "thinkingPulse 1.5s ease-in-out infinite",
					}}>
					<HardHat size={16} strokeWidth={2} color="#FFD700" />
				</div>
			</>
		)
	} else if (mode === "completed") {
		icon = (
			<span
				className="codicon codicon-check"
				style={{ color: "var(--vscode-charts-green)" }}></span>
		)
	} else if (mode === "planning") {
		icon = (
			<>
				<style>{keyframesStyle}</style>
				<div
					style={{
						animation: "planningWrite 2s ease-in-out infinite",
					}}>
					<ClipboardList size={20} strokeWidth={1.2} color="#4A90E2" />
				</div>
			</>
		)
	} else if (mode === "failure") {
		icon = (
			<div style={{ color: "var(--vscode-charts-red)" }}>
				<X size={20} />
			</div>
		)
	}
	return icon
}
